<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
function login_is_blocked(string $email, string $ip): bool { $minutes = max(1, (int)env_value('LOGIN_WINDOW_MINUTES', '15')); $max = max(1, (int)env_value('LOGIN_MAX_ATTEMPTS', '5')); $cutoff = date('Y-m-d H:i:s', time() - ($minutes * 60)); $stmt = db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE email=? AND ip_address=? AND successful=0 AND attempted_at >= ?'); $stmt->execute([$email, $ip, $cutoff]); return (int)$stmt->fetchColumn() >= $max; }
function record_login_attempt(string $email, string $ip, bool $success): void { db()->prepare('INSERT INTO login_attempts(email,ip_address,attempted_at,successful) VALUES(?,?,NOW(),?)')->execute([$email, $ip, $success ? 1 : 0]); }
function login_user(string $email, string $password): bool { $email = strtolower(trim($email)); $ip = client_ip(); if (login_is_blocked($email, $ip)) return false; $stmt = db()->prepare('SELECT u.*, r.slug role_slug, r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? AND u.active=1 LIMIT 1'); $stmt->execute([$email]); $account = $stmt->fetch(); $success = $account && password_verify($password, $account['password_hash']); record_login_attempt($email, $ip, (bool)$success); if (!$success) { audit('login_failed', $account ? (int)$account['id'] : null, $email); return false; } session_regenerate_id(true); $_SESSION['user_id'] = (int)$account['id']; $_SESSION['_csrf'] = bin2hex(random_bytes(32)); db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([(int)$account['id']]); audit('login_success', (int)$account['id']); return true; }
function logout_user(): void { $id = (int)($_SESSION['user_id'] ?? 0); if ($id) audit('logout', $id); $_SESSION = []; if (ini_get('session.use_cookies')) { $params = session_get_cookie_params(); setcookie(session_name(), '', time() - 42000, $params['path'], '', (bool)$params['secure'], (bool)$params['httponly']); } session_destroy(); }
